  const menus=siteSections.map(s=>'<div class="menu"><a href="/'+s.slug+'">'+pageEscape(s.title)+'</a><div class="sub">'+s.children.map(c=>'<a href="/'+s.slug+'/'+c[0]+'">'+pageEscape(c[1])+'</a>').join('')+'</div></div>').join('')+'<a class="sitemap-menu-link" href="/sitemap">전체 사이트 안내</a>';
